use system.fs
use system.os
use system.collections.map

// Removes a trailing carriage return so CRLF input reads the same as LF input.
fn strip_cr(line String) String
    if line.ends_with("\r")
        return line.substring(0, line.length() - 1)
    line

// Splits a record line into its non-empty fields.
fn fields(line String) [String]
    var out = [""]
    out.clear()
    for part in line.split(" ")
        if not part.is_empty()
            out.push(part)
    out

fn main()
    let args = Args()
    if args.length() == 0
        panic("usage: prog <input-file>")

    let fs = Fs()
    var text = ""
    match fs.read_file(args.element_at(0))
        Result.Ok(contents): text = contents
        Result.Err(e): panic("cannot read input file")

    let lines = text.split("\n")
    let max = 9223372036854775807
    let min = -max - 1

    var totals = Map<String, int>()
    var overflowed = Map<String, bool>()

    // The first empty line separates the records from the queries.
    var query_start = lines.length()
    var i = 0
    var separator_found = false
    while i < lines.length() and not separator_found
        if strip_cr(lines[i]).is_empty()
            query_start = i + 1
            separator_found = true
        i = i + 1

    var r = 0
    while r < query_start - 1
        let parts = fields(strip_cr(lines[r]))
        if parts.length() == 2
            let key = parts[0]
            match parts[1].to_int()
                Some(value):
                    if not overflowed.contains_key(key)
                        var current = 0
                        match totals.get(key)
                            Some(t): current = t
                            None: current = 0
                        if (value > 0 and current > max - value) or (value < 0 and current < min - value)
                            overflowed.set(key, true)
                        else
                            totals.set(key, current + value)
                None: panic("invalid value in record")
        r = r + 1

    for q in query_start..lines.length()
        let key = strip_cr(lines[q])
        if not key.is_empty()
            if overflowed.contains_key(key)
                println(f"{key}=overflow")
            else
                match totals.get(key)
                    Some(t): println(f"{key}={t}")
                    None: println(f"{key}=absent")

