    while i < lines.length() and not separator_found
        if strip_cr(lines[i]).is_empty()
            query_start = i + 1
            separator_found = true
        i = i + 1

    var r = 0
    while r < query_start - 1
        let parts = fields(strip_cr(lines[r]))
        if parts.length() == 2
            let key = parts[0]
            match parts[1].to_int()
                Some(value):
                    if not overflowed.contains_key(key)
                        var current = 0
                        match totals.get(key)
                            Some(t): current = t
                            None: current = 0
                        if (value > 0 and current > max - value) or (value < 0 and current < min - value)
                            overflowed.set(key, true)
                        else
                            totals.set(key, current + value)
                None: panic("invalid value in record")
        r = r + 1

    for q in query_start..lines.length()
        let key = strip_cr(lines[q])
        if not key.is_empty()
            if overflowed.contains_key(key)
                println(f"{key}=overflow")
            else
                match totals.get(key)
                    Some(t): println(f"{key}={t}")
                    None: println(f"{key}=absent")
